package com.cosrai.dropship
import org.json.JSONObject
import java.io.*
import java.net.*
import java.security.MessageDigest
import java.util.concurrent.*
import java.util.concurrent.atomic.AtomicBoolean
class V2Service(private val book:PairBook,private val repository:TransferRepository,private val events:ReceiveEvents) {
    fun health()=JSONObject().put("service","DropShip").put("protocol",2).put("version","0.6.0").put("deviceId",book.ownId).put("name",book.ownName()).put("approvalRequired",true).put("receiveReady",repository.readinessIssue==null).put("receiveMessage",repository.readinessIssue?:"")
    fun handle(method:String,path:String,headers:Map<String,String>,body:ByteArray):Pair<Int,JSONObject> = synchronized(repository.gate){
        if(method=="GET"&&path=="/v2/health")return 200 to health()
        if(method=="POST"&&path=="/v2/pair/request"){val j=JSONObject(String(body,Charsets.UTF_8));val t=book.request(j.getString("deviceId"),j.getString("name"),j.getString("nonce"));return 200 to JSONObject().put("requestId",t.requestId).put("code",t.code).put("deviceId",book.ownId).put("name",book.ownName()).put("status",t.status)}
        if(method=="GET"&&path.startsWith("/v2/pair/"))return 200 to book.poll(path.substring(9),headers["x-dropship-nonce"]?:"")
        val owner=book.authenticate(headers)
        try{
        if(method=="POST"&&path=="/v2/transfers")return 200 to status(repository.begin(owner,TransferSpec.parse(JSONObject(String(body,Charsets.UTF_8)))))
        if(path.startsWith("/v2/transfers/")){val parts=path.substring(14).split('/');val id=parts[0]
            if(parts.size==1&&method=="GET")return 200 to status(repository.load(owner,id))
            if(parts.size==1&&method=="PATCH"){val offset=headers["x-dropship-offset"]?.toLongOrNull()?:throw V2Error(400,"전송 위치가 없습니다.");val s=repository.chunk(owner,id,offset,body,headers["x-dropship-chunk-sha256"]?:"");events.progress(s.spec.relativePath,s.offset,s.spec.size);return 200 to status(s)}
            if(parts.size==2&&parts[1]=="commit"&&method=="POST"){val fresh=repository.load(owner,id).receipt==null;val receipt=repository.commit(owner,id);if(fresh)events.completed(receipt);return 201 to receiptJson(receipt)}
        };throw V2Error(404,"지원하지 않는 전송 경로입니다.")
        }catch(e:Exception){if(path.startsWith("/v2/transfers"))events.failed(if(e is V2Error)"HTTP ${e.code} · ${e.message}" else "수신 폴더 저장 실패 · ${e.javaClass.simpleName}: ${e.message?:"저장 권한과 공간을 확인해 주세요."}");throw e}
    }
    private fun status(s:TransferState)=JSONObject().put("offset",s.offset).put("complete",s.receipt!=null).put("receipt",s.receipt?.let{receiptJson(it)}?:JSONObject.NULL)
    fun clearIncomplete()=synchronized(repository.gate){repository.clearIncomplete()}
}
class ReceiverV2(private val service:V2Service,port:Int=8765):Closeable {
    private val server=ServerSocket().apply{reuseAddress=true;bind(InetSocketAddress("0.0.0.0",port),8)}
    private val running=AtomicBoolean(true);private val clients=ConcurrentHashMap.newKeySet<Socket>();private val workers=ThreadPoolExecutor(4,4,0,TimeUnit.SECONDS,ArrayBlockingQueue(8))
    private val thread=Thread({while(running.get())try{val socket=server.accept();socket.soTimeout=60000;clients.add(socket);try{workers.execute{handle(socket)}}catch(_:RejectedExecutionException){clients.remove(socket);socket.close()}}catch(_:IOException){if(!running.get())break}},"DropShip-v2-listener").apply{start()}
    private fun handle(socket:Socket){try{val input=BufferedInputStream(socket.getInputStream(),65536);val request=line(input).split(' ');if(request.size!=3||request[2]!="HTTP/1.1")throw V2Error(400,"요청 형식이 올바르지 않습니다.");val headers=mutableMapOf<String,String>();var count=0;while(true){val h=line(input);count+=h.length;if(count>16384||headers.size>40)throw V2Error(431,"요청 정보가 너무 큽니다.");if(h.isEmpty())break;val at=h.indexOf(':');if(at<=0||headers.put(h.substring(0,at).lowercase(),h.substring(at+1).trim())!=null)throw V2Error(400,"중복되거나 잘못된 요청 정보입니다.")};if(headers.containsKey("transfer-encoding"))throw V2Error(400,"고정 크기 요청만 지원합니다.");val length=if(headers.containsKey("content-length"))headers["content-length"]!!.toIntOrNull()?:throw V2Error(400,"요청 크기가 올바르지 않습니다.") else 0;val limit=if(request[0]=="PATCH")1048576 else 16384;if(length<0||length>limit)throw V2Error(413,"요청 크기가 너무 큽니다.");val body=ByteArray(length);var read=0;while(read<length){val n=input.read(body,read,length-read);if(n<0)throw EOFException();read+=n};val(code,json)=service.handle(request[0],request[1],headers,body);respond(socket,code,json)}catch(e:Exception){val code=if(e is V2Error)e.code else 400;val message=if(e is V2Error)e.message else "저장 공간이나 연결을 확인해 주세요.";try{respond(socket,code,JSONObject().put("error",message))}catch(_:Exception){}}finally{clients.remove(socket);socket.close()}}
    private fun line(input:InputStream):String{val out=ByteArrayOutputStream();while(out.size()<=4096){val c=input.read();if(c<0)throw EOFException();if(c==10){val b=out.toByteArray();if(b.isEmpty()||b.last()!=13.toByte())throw V2Error(400,"요청 형식이 올바르지 않습니다.");return String(b,0,b.size-1,Charsets.US_ASCII)};out.write(c)};throw V2Error(431,"요청 정보가 너무 큽니다.")}
    private fun respond(socket:Socket,code:Int,json:JSONObject){val b=json.toString().toByteArray(Charsets.UTF_8);val h="HTTP/1.1 $code ${if(code<300)"OK" else "Error"}\r\nContent-Type: application/json; charset=utf-8\r\nContent-Length: ${b.size}\r\nConnection: close\r\n\r\n".toByteArray(Charsets.US_ASCII);socket.getOutputStream().apply{write(h);write(b);flush()}}
    override fun close(){running.set(false);server.close();clients.forEach{try{it.close()}catch(_:Exception){}};workers.shutdown();thread.join(1000)}
}
class ClientV2(private val book:PairBook) {
    fun request(ep:DeviceEndpoint,method:String,path:String,json:JSONObject?,control:SendControl,target:String?=null,body:ByteArray?=null,extra:Map<String,String> = emptyMap()):JSONObject {
        control.check();val bytes=body?:json?.toString()?.toByteArray(Charsets.UTF_8)?:byteArrayOf();val headers=mutableMapOf<String,String>();if(target!=null){val device=book.find(target)?:throw V2Error(403,"먼저 기기 연결을 승인해 주세요.");headers["X-DropShip-Device"]=book.ownId;headers["X-DropShip-Target"]=target;headers["X-DropShip-Token"]=device.token};headers.putAll(extra)
        Socket().use{socket->control.attach(socket);control.check();socket.connect(InetSocketAddress(ep.ip,ep.port),5000);socket.soTimeout=60000
            val h=buildString{append("$method $path HTTP/1.1\r\nHost: ${ep.ip}:${ep.port}\r\nContent-Length: ${bytes.size}\r\nConnection: close\r\n");headers.forEach{(k,v)->require(!v.contains('\r')&&!v.contains('\n'));append("$k: $v\r\n")};append("\r\n")}.toByteArray(Charsets.US_ASCII)
            val watchdog=Executors.newSingleThreadScheduledExecutor();watchdog.schedule({try{socket.close()}catch(_:Exception){}},60,TimeUnit.SECONDS)
            try{socket.getOutputStream().apply{write(h);write(bytes);flush()};val input=BufferedInputStream(socket.getInputStream());val status=line(input).split(' ');val code=status.getOrNull(1)?.toIntOrNull()?:throw IOException("응답 형식이 올바르지 않습니다.");var length=-1;var count=0;var total=0;while(true){val s=line(input);total+=s.length;if(++count>40||total>16384)throw IOException("응답 정보가 너무 큽니다.");if(s.isEmpty())break;val at=s.indexOf(':');if(at<=0)throw IOException("응답 형식이 올바르지 않습니다.");if(s.substring(0,at).equals("Content-Length",true)){if(length!=-1)throw IOException("중복된 응답 정보입니다.");length=s.substring(at+1).trim().toIntOrNull()?:-1}};if(length !in 0..16384)throw IOException("응답 크기가 올바르지 않습니다.");val result=ByteArray(length);var read=0;while(read<length){val n=input.read(result,read,length-read);if(n<0)throw EOFException();read+=n};val j=JSONObject(String(result,Charsets.UTF_8));if(code !in 200..299)throw V2Error(code,j.optString("error","전송을 완료하지 못했습니다."));return j}catch(e:IOException){control.check();throw e}finally{watchdog.shutdownNow()}}
    }
    private fun line(input:InputStream):String{val out=ByteArrayOutputStream();while(out.size()<=4096){val c=input.read();if(c<0)throw EOFException();if(c==10){val b=out.toByteArray();if(b.isEmpty()||b.last()!=13.toByte())throw IOException("응답 형식이 올바르지 않습니다.");return String(b,0,b.size-1,Charsets.US_ASCII)};out.write(c)};throw IOException("응답 정보가 너무 큽니다.")}
    fun inspect(ep:DeviceEndpoint,control:SendControl):RemoteInfo{val j=request(ep,"GET","/v2/health",null,control);if(j.getString("service")!="DropShip"||j.getInt("protocol")!=2)throw V2Error(400,"양쪽에서 v0.5 이상을 실행해 주세요.");val id=j.getString("deviceId");if(!V2Json.hex(id,32)||id==book.ownId)throw V2Error(400,"다른 기기를 선택해 주세요.");return RemoteInfo(id,j.optString("name","DropShip"),j.optBoolean("receiveReady",true),j.optString("receiveMessage"))}
    fun health(ep:DeviceEndpoint,control:SendControl)=inspect(ep,control).id
    fun pair(ep:DeviceEndpoint,showCode:(String,String)->Unit,control:SendControl){val nonce=V2Json.id();val start=request(ep,"POST","/v2/pair/request",JSONObject().put("deviceId",book.ownId).put("name",book.ownName()).put("nonce",nonce),control);val id=start.getString("requestId");val remote=start.getString("deviceId");showCode(start.getString("name"),start.getString("code"));val end=System.currentTimeMillis()+120000;while(System.currentTimeMillis()<end){control.check();Thread.sleep(1000);val j=request(ep,"GET","/v2/pair/$id",null,control,extra=mapOf("X-DropShip-Nonce" to nonce));if(j.getString("deviceId")!=remote)throw V2Error(403,"다른 기기가 응답했습니다.");if(j.getString("status")=="rejected")throw V2Error(403,"상대 기기에서 연결을 거절했습니다.");if(j.getString("status")=="approved"){book.put(remote,j.getString("name"),j.getString("token"));return}};throw V2Error(408,"연결 승인 시간이 지났습니다.")}
    fun send(ep:DeviceEndpoint,target:String,file:File,relative:String,transferId:String,batchId:String,directory:Boolean,events:SendEvents,control:SendControl):Receipt {
        V2Json.path(relative);val remote=inspect(ep,control);if(remote.id!=target)throw V2Error(403,"기기 주소가 바뀌었습니다. 다시 검색해 주세요.");if(!remote.receiveReady)throw V2Error(409,remote.receiveMessage.ifEmpty{"받는 기기에서 수신 폴더를 설정해 주세요."});val total=if(directory)0 else file.length();events.progress("원본 확인",0,total);val hash=if(directory)V2Json.hash(byteArrayOf()) else {val digest=MessageDigest.getInstance("SHA-256");file.inputStream().use{input->val b=ByteArray(131072);while(true){control.check();val n=input.read(b);if(n<0)break;digest.update(b,0,n)}};digest.digest().joinToString(""){"%02x".format(it.toInt() and 255)}}
        val spec=TransferSpec(transferId,batchId,relative,total,hash,directory);val state=request(ep,"POST","/v2/transfers",spec.json(),control,target)
        if(!state.getBoolean("complete")&&!directory){var offset=state.getLong("offset");if(offset<0||offset>total)throw V2Error(409,"수신 위치가 올바르지 않습니다.");events.progress(if(offset>0)"이어보내기" else "전송 중",offset,total);RandomAccessFile(file,"r").use{input->input.seek(offset);val buffer=ByteArray(1048576);while(offset<total){control.check();val count=minOf(buffer.size.toLong(),total-offset).toInt();input.readFully(buffer,0,count);val chunk=buffer.copyOf(count);val j=request(ep,"PATCH","/v2/transfers/$transferId",null,control,target,chunk,mapOf("X-DropShip-Offset" to offset.toString(),"X-DropShip-Chunk-SHA256" to V2Json.hash(chunk)));val next=j.getLong("offset");if(next!=offset+count)throw V2Error(409,"수신 위치가 일치하지 않습니다.");offset=next;events.progress("전송 중",offset,total)}}}
        control.check();events.progress("저장·검증",total,total);val receipt=receiptParse(request(ep,"POST","/v2/transfers/$transferId/commit",JSONObject(),control,target));if(receipt.size!=total||receipt.sha256!=hash||receipt.name.isEmpty()||receipt.path.isEmpty())throw V2Error(422,"수신 검증 결과가 일치하지 않습니다.");return receipt
    }
}
